using System.Diagnostics;
using System.Runtime;
using System.Threading;
namespace PoloOS.Diagnostics.Core;
public sealed class FtdiD2xxTransport:IDisposable
{
    private IntPtr _handle=IntPtr.Zero; private readonly DiagLog _log; public int DeviceIndex{get;} public int Baud{get;private set;} public int DefaultReadTimeoutMs{get;set;}=1800;
    public FtdiD2xxTransport(int deviceIndex,DiagLog log){DeviceIndex=deviceIndex;_log=log;}
    public static int GetDeviceCount(){uint count=0;Check(FtdiNative.FT_CreateDeviceInfoList(ref count),"FT_CreateDeviceInfoList");return checked((int)count);}
    public void Open(int baud){Close();IntPtr h=IntPtr.Zero;Check(FtdiNative.FT_Open(DeviceIndex,ref h),"FT_Open");_handle=h;try{Check(FtdiNative.FT_ResetDevice(_handle),"FT_ResetDevice");SetBaud(baud);Check(FtdiNative.FT_SetDataCharacteristics(_handle,8,0,0),"FT_SetDataCharacteristics");Check(FtdiNative.FT_SetFlowControl(_handle,0,0,0),"FT_SetFlowControl");Check(FtdiNative.FT_SetTimeouts(_handle,100,500),"FT_SetTimeouts");byte before=0;_=FtdiNative.FT_GetLatencyTimer(_handle,ref before);Check(FtdiNative.FT_SetLatencyTimer(_handle,1),"FT_SetLatencyTimer");byte after=0;_=FtdiNative.FT_GetLatencyTimer(_handle,ref after);ClearBuffers();SetBreak(false);_log.Write($"FT_OPEN index={DeviceIndex} baud={baud} latency={before}->{after}");}catch{Close();throw;}}
    public void SetBaud(int baud){EnsureOpen();Check(FtdiNative.FT_SetBaudRate(_handle,checked((uint)baud)),"FT_SetBaudRate");Baud=baud;} public void ClearBuffers(){EnsureOpen();Check(FtdiNative.FT_Purge(_handle,FtdiNative.FT_PURGE_RX|FtdiNative.FT_PURGE_TX),"FT_Purge");} public void ClearReceiveBuffer(){EnsureOpen();Check(FtdiNative.FT_Purge(_handle,FtdiNative.FT_PURGE_RX),"FT_Purge RX");} public void SetBreak(bool enabled){EnsureOpen();Check(enabled?FtdiNative.FT_SetBreakOn(_handle):FtdiNative.FT_SetBreakOff(_handle),enabled?"FT_SetBreakOn":"FT_SetBreakOff");}
    public void WriteRaw(byte value){EnsureOpen();var buffer=new[]{value};uint written=0;Check(FtdiNative.FT_Write(_handle,buffer,1,ref written),"FT_Write");if(written!=1)throw new IOException($"FT_Write wrote {written} bytes instead of 1.");} public byte WriteByteAndDiscardEcho(byte value,int echoTimeoutMs=500){WriteRaw(value);return ReadByte(echoTimeoutMs);}
    public byte ReadByte(int? timeoutMs=null){EnsureOpen();var timeout=timeoutMs??DefaultReadTimeoutMs;var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<timeout){uint queued=0;Check(FtdiNative.FT_GetQueueStatus(_handle,ref queued),"FT_GetQueueStatus");if(queued>0){var buffer=new byte[1];uint read=0;Check(FtdiNative.FT_Read(_handle,buffer,1,ref read),"FT_Read");if(read==1)return buffer[0];}Thread.SpinWait(40);if(sw.ElapsedMilliseconds>2)Thread.Sleep(0);}throw new TimeoutException($"K-line read timeout after {timeout} ms.");}
    public byte? TryReadByte(int timeoutMs){try{return ReadByte(timeoutMs);}catch(TimeoutException){return null;}}
    public void FiveBaudInit(byte controllerAddress,bool evenParity,int bitMilliseconds){EnsureOpen();var noGc=false;try{try{noGc=GC.TryStartNoGCRegion(1024*1024);}catch{}Thread.Sleep(300);SetBreak(false);var value=AdjustParity(controllerAddress,evenParity);SendBit(false,bitMilliseconds);for(var i=0;i<8;i++){SendBit((value&0x01)!=0,bitMilliseconds);value>>=1;}SendBit(true,bitMilliseconds);ClearReceiveBuffer();}finally{if(noGc&&GCSettings.LatencyMode==GCLatencyMode.NoGCRegion){try{GC.EndNoGCRegion();}catch{}}}}
    private void SendBit(bool logicalHigh,int bitMilliseconds){SetBreak(!logicalHigh);PreciseDelay.Milliseconds(bitMilliseconds);} public static byte AdjustParity(byte value,bool evenParity){var seven=value&0x7F;var ones=0;for(var i=0;i<7;i++)ones+=(seven>>i)&1;var parityBit=evenParity?(ones%2==0?0:1):(ones%2==0?1:0);return(byte)(seven|(parityBit<<7));}
    public void Close(){if(_handle==IntPtr.Zero)return;try{_=FtdiNative.FT_SetBreakOff(_handle);}catch{}try{_=FtdiNative.FT_Close(_handle);}catch{}_handle=IntPtr.Zero;Baud=0;} public void Dispose()=>Close(); private void EnsureOpen(){if(_handle==IntPtr.Zero)throw new InvalidOperationException("FTDI device is not open.");} private static void Check(uint status,string operation){if(status!=FtdiNative.FT_OK)throw new IOException($"{operation} failed. FT_STATUS={status}");}
}
